SELECT *, (
(CASE WHEN keywords LIKE CONCAT('%', #{token}, '%') THEN 2 ELSE 0 END + CASE WHEN question LIKE CONCAT('%', #{token}, '%') THEN 1 ELSE 0 END + CASE WHEN answer LIKE CONCAT('%', #{token}, '%') THEN 1 ELSE 0 END)
) AS relevance_score FROM ai_knowledge_base WHERE status = 1 AND (
keywords LIKE CONCAT('%', #{token}, '%') OR question LIKE CONCAT('%', #{token}, '%')
) HAVING relevance_score > 0 ORDER BY relevance_score DESC, hit_count DESC LIMIT #{limit}

SELECT * FROM ai_knowledge_base
AND (question LIKE CONCAT('%', #{keyword}, '%') OR keywords LIKE CONCAT('%', #{keyword}, '%'))
ORDER BY id DESC LIMIT #{offset}, #{limit}

mapper.update:
UPDATE ai_knowledge_base
SET question = #{question}, answer = #{answer}, category_id = #{categoryId},
    keywords = #{keywords}, status = #{status}
WHERE id = #{id}
